  1	// SPDX-License-Identifier: MIT
  2	
  3	pragma solidity ^0.8.28;
  4	
  5	import {IForeignGateway} from "./interfaces/IForeignGateway.sol";
  6	import {IArbitrableV2} from "../arbitration/interfaces/IArbitrableV2.sol";
  7	import {IArbitratorV2} from "../arbitration/interfaces/IArbitratorV2.sol";
  8	import {IReceiverGateway} from "@kleros/vea-contracts/src/interfaces/gateways/IReceiverGateway.sol";
  9	import {UUPSProxiable} from "../proxy/UUPSProxiable.sol";
 10	import {Initializable} from "../proxy/Initializable.sol";
 11	import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
 12	import "../libraries/Constants.sol";
 13	
 14	/// @title Foreign Gateway
 15	/// @notice Counterpart of `HomeGateway`
 16	contract ForeignGateway is IForeignGateway, UUPSProxiable, Initializable {
 17	    string public constant override version = "0.8.0";
 18	
 19	    // ************************************* //
 20	    // *         Enums / Structs           * //
 21	    // ************************************* //
 22	
 23	    struct DisputeData {
 24	        uint248 id;
 25	        bool ruled;
 26	        address arbitrable;
 27	        uint256 paid;
 28	        address relayer;
 29	    }
 30	
 31	    // ************************************* //
 32	    // *              Events               * //
 33	    // ************************************* //
 34	
 35	    event ArbitrationCostModified(uint96 indexed _courtID, uint256 _feeForJuror);
 36	
 37	    // ************************************* //
 38	    // *             Storage               * //
 39	    // ************************************* //
 40	
 41	    uint256 internal localDisputeID; // The disputeID must start from 1 as the KlerosV1 proxy governor depends on this implementation. We now also depend on localDisputeID not ever being zero.
 42	    mapping(uint96 courtId => uint256) public feeForJuror; // feeForJuror[v2CourtID], it mirrors the value on KlerosCore.
 43	    address public owner;
 44	    address public veaOutbox;
 45	    uint256 public override homeChainID;
 46	    address public override homeGateway;
 47	    address public deprecatedVeaOutbox;
 48	    uint256 public deprecatedVeaOutboxExpiration;
 49	    mapping(bytes32 disputeHash => DisputeData) public disputeHashtoDisputeData;
 50	
 51	    // ************************************* //
 52	    // *        Function Modifiers         * //
 53	    // ************************************* //
 54	
 55	    modifier onlyFromVea(address _messageSender) {
 56	        require(
 57	            veaOutbox == msg.sender ||
 58	                (block.timestamp < deprecatedVeaOutboxExpiration && deprecatedVeaOutbox == msg.sender),
 59	            VeaOutboxOnly()
 60	        );
 61	        require(_messageSender == homeGateway, HomeGatewayMessageSenderOnly());
 62	        _;
 63	    }
 64	
 65	    modifier onlyByOwner() {
 66	        require(owner == msg.sender, OwnerOnly());
 67	        _;
 68	    }
 69	
 70	    // ************************************* //
 71	    // *            Constructor            * //
 72	    // ************************************* //
 73	
 74	    /// @custom:oz-upgrades-unsafe-allow constructor
 75	    constructor() {
 76	        _disableInitializers();
 77	    }
 78	
 79	    /// @notice Constructs the `PolicyRegistry` contract.
 80	    /// @param _owner The owner's address.
 81	    /// @param _veaOutbox The address of the VeaOutbox.
 82	    /// @param _homeChainID The chainID of the home chain.
 83	    /// @param _homeGateway The address of the home gateway.
 84	    function initialize(
 85	        address _owner,
 86	        address _veaOutbox,
 87	        uint256 _homeChainID,
 88	        address _homeGateway
 89	    ) external initializer {
 90	        owner = _owner;
 91	        veaOutbox = _veaOutbox;
 92	        homeChainID = _homeChainID;
 93	        homeGateway = _homeGateway;
 94	        localDisputeID = 1;
 95	    }
 96	
 97	    // ************************************* //
 98	    // *           Governance              * //
 99	    // ************************************* //
100	
101	    /**
102	     * @dev Access Control to perform implementation upgrades (UUPS Proxiable)
103	     * @dev Only the owner can perform upgrades (`onlyByOwner`)
104	     */
105	    function _authorizeUpgrade(address) internal view override onlyByOwner {
106	        // NOP
107	    }
108	
109	    /// @notice Changes the owner.
110	    /// @param _owner The address of the new owner.
111	    function changeOwner(address _owner) external onlyByOwner {
112	        owner = _owner;
113	    }
114	
115	    /// @notice Changes the outbox.
116	    /// @param _veaOutbox The address of the new outbox.
117	    /// @param _gracePeriod The duration to accept messages from the deprecated bridge (if at all).
118	    function changeVea(address _veaOutbox, uint256 _gracePeriod) external onlyByOwner {
119	        // grace period to relay the remaining messages which are still going through the deprecated bridge.
120	        deprecatedVeaOutboxExpiration = block.timestamp + _gracePeriod;
121	        deprecatedVeaOutbox = veaOutbox;
122	        veaOutbox = _veaOutbox;
123	    }
124	
125	    /// @notice Changes the home gateway.
126	    /// @param _homeGateway The address of the new home gateway.
127	    function changeHomeGateway(address _homeGateway) external onlyByOwner {
128	        homeGateway = _homeGateway;
129	    }
130	
131	    /// @notice Changes the `feeForJuror` property value of a specified court.
132	    /// @param _courtID The ID of the court on the v2 arbitrator. Not to be confused with the courtID on KlerosLiquid.
133	    /// @param _feeForJuror The new value for the `feeForJuror` property value.
134	    function changeCourtJurorFee(uint96 _courtID, uint256 _feeForJuror) external onlyByOwner {
135	        feeForJuror[_courtID] = _feeForJuror;
136	        emit ArbitrationCostModified(_courtID, _feeForJuror);
137	    }
138	
139	    // ************************************* //
140	    // *         State Modifiers           * //
141	    // ************************************* //
142	
143	    /// @notice Create a dispute and pay for the fees in the native currency, typically ETH.
144	    /// @dev Must be called by the arbitrable contract and pay at least `arbitrationCost(_extraData)` in ETH.
145	    /// @param _choices The number of choices the arbitrator can choose from in this dispute.
146	    /// @param _extraData Additional info about the dispute. We use it to pass the ID of the dispute's court (first 32 bytes), the minimum number of jurors required (next 32 bytes) and the ID of the specific dispute kit (last 32 bytes).
147	    /// @return disputeID The identifier of the dispute created.
148	    function createDispute(
149	        uint256 _choices,
150	        bytes calldata _extraData
151	    ) external payable override returns (uint256 disputeID) {
152	        require(msg.value >= arbitrationCost(_extraData), ArbitrationFeesNotEnough());
153	
154	        disputeID = localDisputeID++;
155	        uint256 chainID;
156	        assembly {
157	            chainID := chainid()
158	        }
159	        bytes32 disputeHash = keccak256(
160	            abi.encodePacked(
161	                "createDispute",
162	                blockhash(block.number - 1),
163	                chainID,
164	                msg.sender,
165	                disputeID,
166	                _choices,
167	                _extraData
168	            )
169	        );
170	
171	        disputeHashtoDisputeData[disputeHash] = DisputeData({
172	            id: uint248(disputeID),
173	            arbitrable: msg.sender,
174	            paid: msg.value,
175	            relayer: address(0),
176	            ruled: false
177	        });
178	
179	        emit CrossChainDisputeOutgoing(blockhash(block.number - 1), msg.sender, disputeID, _choices, _extraData);
180	    }
181	
182	    function createDispute(
183	        uint256 /*_choices*/,
184	        bytes calldata /*_extraData*/,
185	        IERC20 /*_feeToken*/,
186	        uint256 /*_feeAmount*/
187	    ) external pure override returns (uint256) {
188	        revert("Not supported");
189	    }
190	
191	    /// @notice Compute the cost of arbitration denominated in the native currency, typically ETH.
192	    /// @dev It is recommended not to increase it often, as it can be highly time and gas consuming for the arbitrated contracts to cope with fee augmentation.
193	    /// @param _extraData Additional info about the dispute. We use it to pass the ID of the dispute's court (first 32 bytes), the minimum number of jurors required (next 32 bytes) and the ID of the specific dispute kit (last 32 bytes).
194	    /// @return cost The arbitration cost in ETH.
195	    function arbitrationCost(bytes calldata _extraData) public view override returns (uint256 cost) {
196	        (uint96 courtID, uint256 minJurors) = extraDataToCourtIDMinJurors(_extraData);
197	        cost = feeForJuror[courtID] * minJurors;
198	    }
199	
200	    function arbitrationCost(
201	        bytes calldata /*_extraData*/,
202	        IERC20 /*_feeToken*/
203	    ) public pure override returns (uint256 /*cost*/) {
204	        revert("Not supported");
205	    }
206	
207	    /// @notice Relay the rule call from the home gateway to the arbitrable.
208	    /// @param _messageSender The address of the message sender.
209	    /// @param _disputeHash The dispute hash.
210	    /// @param _ruling The ruling.
211	    /// @param _relayer The address of the relayer.
212	    function relayRule(
213	        address _messageSender,
214	        bytes32 _disputeHash,
215	        uint256 _ruling,
216	        address _relayer
217	    ) external override onlyFromVea(_messageSender) {
218	        DisputeData storage dispute = disputeHashtoDisputeData[_disputeHash];
219	
220	        require(dispute.id != 0, DisputeDoesNotExist());
221	        require(!dispute.ruled, CannotRuleTwice());
222	
223	        dispute.ruled = true;
224	        dispute.relayer = _relayer;
225	
226	        IArbitrableV2 arbitrable = IArbitrableV2(dispute.arbitrable);
227	        arbitrable.rule(dispute.id, _ruling);
228	    }
229	
230	    /// @notice Reimburses the dispute fees to the relayer who paid for these fees on the home chain.
231	    /// @param _disputeHash The dispute hash for which to withdraw the fees.
232	    function withdrawFees(bytes32 _disputeHash) external override {
233	        DisputeData storage dispute = disputeHashtoDisputeData[_disputeHash];
234	        require(dispute.id != 0, DisputeDoesNotExist());
235	        require(dispute.ruled, NotRuledYet());
236	
237	        uint256 amount = dispute.paid;
238	        dispute.paid = 0;
239	        payable(dispute.relayer).transfer(amount);
240	    }
241	
242	    // ************************************* //
243	    // *           Public Views            * //
244	    // ************************************* //
245	
246	    /// @notice Looks up the local foreign disputeID for a disputeHash
247	    /// @param _disputeHash The dispute hash.
248	    /// @return The local foreign disputeID.
249	    function disputeHashToForeignID(bytes32 _disputeHash) external view override returns (uint256) {
250	        return disputeHashtoDisputeData[_disputeHash].id;
251	    }
252	
253	    function senderGateway() external view override returns (address) {
254	        return homeGateway;
255	    }
256	
257	    function currentRuling(
258	        uint256 /*_disputeID*/
259	    ) public pure returns (uint256 /*ruling*/, bool /*tied*/, bool /*overridden*/) {
260	        revert("Not supported");
261	    }
262	
263	    // ************************************* //
264	    // *            Internal               * //
265	    // ************************************* //
266	
267	    function extraDataToCourtIDMinJurors(
268	        bytes memory _extraData
269	    ) internal view returns (uint96 courtID, uint256 minJurors) {
270	        // Note that here we ignore DisputeKitID
271	        if (_extraData.length >= 64) {
272	            assembly {
273	                // solium-disable-line security/no-inline-assembly
274	                courtID := mload(add(_extraData, 0x20))
275	                minJurors := mload(add(_extraData, 0x40))
276	            }
277	            if (feeForJuror[courtID] == 0) courtID = 0;
278	            if (minJurors == 0) minJurors = DEFAULT_NB_OF_JURORS;
279	        } else {
280	            courtID = 0;
281	            minJurors = DEFAULT_NB_OF_JURORS;
282	        }
283	    }
284	
285	    // ************************************* //
286	    // *              Errors               * //
287	    // ************************************* //
288	
289	    error OwnerOnly();
290	    error HomeGatewayMessageSenderOnly();
291	    error VeaOutboxOnly();
292	    error ArbitrationFeesNotEnough();
293	    error DisputeDoesNotExist();
294	    error CannotRuleTwice();
295	    error NotRuledYet();
296	}

