  3	pragma solidity ^0.8.28;
  4	
  5	import {IVeaInbox} from "@kleros/vea-contracts/src/interfaces/inboxes/IVeaInbox.sol";
  6	import {ISenderGateway} from "@kleros/vea-contracts/src/interfaces/gateways/ISenderGateway.sol";
  7	import {IForeignGateway} from "./interfaces/IForeignGateway.sol";
  8	import {IHomeGateway} from "./interfaces/IHomeGateway.sol";
  9	import {IArbitratorV2} from "../arbitration/interfaces/IArbitratorV2.sol";
 10	import {IArbitrableV2} from "../arbitration/interfaces/IArbitrableV2.sol";
 11	import {SafeERC20} from "../libraries/SafeERC20.sol";
 12	import {UUPSProxiable} from "../proxy/UUPSProxiable.sol";
 13	import {Initializable} from "../proxy/Initializable.sol";
 14	import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
 15	import "../libraries/Constants.sol";
 16	
 17	/// @title Home Gateway
 18	/// @notice Counterpart of `ForeignGateway`
 19	contract HomeGateway is IHomeGateway, UUPSProxiable, Initializable {
 20	    using SafeERC20 for IERC20;
 21	
 22	    string public constant override version = "0.8.0";
 23	
 24	    // ************************************* //
 25	    // *         Enums / Structs           * //
 26	    // ************************************* //
 27	
 28	    struct RelayedData {
 29	        uint256 arbitrationCost;
 30	        address relayer;
 31	    }
 32	
 33	    // ************************************* //
 34	    // *             Storage               * //
 35	    // ************************************* //
 36	
 37	    address public owner;
 38	    IArbitratorV2 public arbitrator;
 39	    IVeaInbox public veaInbox;
 40	    uint256 public override foreignChainID;
 41	    address public override foreignGateway;
 42	    IERC20 public feeToken;
 43	    mapping(uint256 => bytes32) public disputeIDtoHash;
 44	    mapping(bytes32 => uint256) public disputeHashtoID;
 45	    mapping(bytes32 => RelayedData) public disputeHashtoRelayedData;
 46	
 47	    // ************************************* //
 48	    // *        Function Modifiers         * //
 49	    // ************************************* //
 50	
 51	    /// @notice Requires that the sender is the owner.
 52	    modifier onlyByOwner() {
 53	        require(owner == msg.sender, OwnerOnly());
 54	        _;
 55	    }
 56	
 57	    // ************************************* //
 58	    // *            Constructor            * //
 59	    // ************************************* //
 60	
 61	    /// @custom:oz-upgrades-unsafe-allow constructor
 62	    constructor() {
 63	        _disableInitializers();
 64	    }
 65	
 66	    /// @notice Constructs the `PolicyRegistry` contract.
 67	    /// @param _owner The owner's address.
 68	    /// @param _arbitrator The address of the arbitrator.
 69	    /// @param _veaInbox The address of the vea inbox.
 70	    /// @param _foreignChainID The ID of the foreign chain.
 71	    /// @param _foreignGateway The address of the foreign gateway.
 72	    /// @param _feeToken The address of the fee token.
 73	    function initialize(
 74	        address _owner,
 75	        IArbitratorV2 _arbitrator,
 76	        IVeaInbox _veaInbox,
 77	        uint256 _foreignChainID,
 78	        address _foreignGateway,
 79	        IERC20 _feeToken
 80	    ) external initializer {
 81	        owner = _owner;
 82	        arbitrator = _arbitrator;
 83	        veaInbox = _veaInbox;
 84	        foreignChainID = _foreignChainID;
 85	        foreignGateway = _foreignGateway;
 86	        feeToken = _feeToken;
 87	    }
 88	
 89	    // ************************************* //
 90	    // *           Governance              * //
 91	    // ************************************* //
 92	
 93	    /**
 94	     * @dev Access Control to perform implementation upgrades (UUPS Proxiable)
 95	     * @dev Only the owner can perform upgrades (`onlyByOwner`)
 96	     */
 97	    function _authorizeUpgrade(address) internal view override onlyByOwner {
 98	        // NOP
 99	    }
100	
101	    /// @notice Changes the owner.
102	    /// @param _owner The address of the new owner.
103	    function changeOwner(address _owner) external onlyByOwner {
104	        owner = _owner;
105	    }
106	
107	    /// @notice Changes the arbitrator.
108	    /// @param _arbitrator The address of the new arbitrator.
109	    function changeArbitrator(IArbitratorV2 _arbitrator) external onlyByOwner {
110	        arbitrator = _arbitrator;
111	    }
112	
113	    /// @notice Changes the vea inbox, useful to increase the claim deposit.
114	    /// @param _veaInbox The address of the new vea inbox.
115	    function changeVea(IVeaInbox _veaInbox) external onlyByOwner {
116	        veaInbox = _veaInbox;
117	    }
118	
119	    /// @notice Changes the foreign gateway.
120	    /// @param _foreignGateway The address of the new foreign gateway.
121	    function changeForeignGateway(address _foreignGateway) external onlyByOwner {
122	        foreignGateway = _foreignGateway;
123	    }
124	
125	    /// @notice Changes the fee token.
126	    /// @param _feeToken The address of the new fee token.
127	    function changeFeeToken(IERC20 _feeToken) external onlyByOwner {
128	        feeToken = _feeToken;
129	    }
130	
131	    // ************************************* //
132	    // *         State Modifiers           * //
133	    // ************************************* //
134	
135	    /// @notice Relays a dispute creation from the ForeignGateway to the home arbitrator using the same parameters as the ones on the foreign chain.
136	    ///
137	    /// @dev Providing incorrect parameters will create a different hash than on the foreignChain and will not affect the actual dispute/arbitrable's ruling.
138	    /// This function accepts the fees payment in the native currency of the home chain, typically ETH.
139	    ///
140	    /// @param _params The parameters of the dispute, see `RelayCreateDisputeParams`.
141	    function relayCreateDispute(RelayCreateDisputeParams memory _params) external payable override {
142	        require(feeToken == NATIVE_CURRENCY, FeesPaidInNativeCurrencyOnly());
143	        require(_params.foreignChainID == foreignChainID, ForeignChainIDNotSupported());
144	
145	        bytes32 disputeHash = keccak256(
146	            abi.encodePacked(
147	                "createDispute",
148	                _params.foreignBlockHash,
149	                _params.foreignChainID,
150	                _params.foreignArbitrable,
151	                _params.foreignDisputeID,
152	                _params.choices,
153	                _params.extraData
154	            )
155	        );
156	        RelayedData storage relayedData = disputeHashtoRelayedData[disputeHash];
157	        require(relayedData.relayer == address(0), DisputeAlreadyRelayed());
158	
159	        uint256 disputeID = arbitrator.createDispute{value: msg.value}(_params.choices, _params.extraData);
160	        disputeIDtoHash[disputeID] = disputeHash;
161	        disputeHashtoID[disputeHash] = disputeID;
162	        relayedData.relayer = msg.sender;
163	
164	        emit DisputeRequest(arbitrator, disputeID, _params.templateId);
165	
166	        emit CrossChainDisputeIncoming(
167	            arbitrator,
168	            _params.foreignChainID,
169	            _params.foreignArbitrable,
170	            _params.foreignDisputeID,
171	            disputeID,
172	            _params.templateId
173	        );
174	    }
175	
176	    /// @notice Relays a dispute creation from the ForeignGateway to the home arbitrator using the same parameters as the ones on the foreign chain.
177	    ///
178	    /// @dev Providing incorrect parameters will create a different hash than on the foreignChain and will not affect the actual dispute/arbitrable's ruling.
179	    /// This function accepts the fees payment in the ERC20 `acceptedFeeToken()`.
180	    ///
181	    /// @param _params The parameters of the dispute, see `RelayCreateDisputeParams`.
182	    function relayCreateDispute(RelayCreateDisputeParams memory _params, uint256 _feeAmount) external {
183	        require(feeToken != NATIVE_CURRENCY, FeesPaidInERC20Only());
184	        require(_params.foreignChainID == foreignChainID, ForeignChainIDNotSupported());
185	
186	        bytes32 disputeHash = keccak256(
187	            abi.encodePacked(
188	                "createDispute",
189	                _params.foreignBlockHash,
190	                _params.foreignChainID,
191	                _params.foreignArbitrable,
192	                _params.foreignDisputeID,
193	                _params.choices,
194	                _params.extraData
195	            )
196	        );
197	        RelayedData storage relayedData = disputeHashtoRelayedData[disputeHash];
198	        require(relayedData.relayer == address(0), DisputeAlreadyRelayed());
199	
200	        require(feeToken.safeTransferFrom(msg.sender, address(this), _feeAmount), TransferFailed());
201	        require(feeToken.increaseAllowance(address(arbitrator), _feeAmount), AllowanceIncreaseFailed());
202	
203	        uint256 disputeID = arbitrator.createDispute(_params.choices, _params.extraData, feeToken, _feeAmount);
204	        disputeIDtoHash[disputeID] = disputeHash;
205	        disputeHashtoID[disputeHash] = disputeID;
206	        relayedData.relayer = msg.sender;
207	
208	        // Not strictly necessary for functionality, only to satisfy IArbitrableV2
209	        emit DisputeRequest(arbitrator, disputeID, _params.templateId);
210	
211	        emit CrossChainDisputeIncoming(
212	            arbitrator,
213	            _params.foreignChainID,
214	            _params.foreignArbitrable,
215	            _params.foreignDisputeID,
216	            disputeID,
217	            _params.templateId
218	        );
219	    }
220	
221	    /// @notice Give a ruling for a dispute.
222	    ///
223	    /// @dev This is a callback function for the arbitrator to provide the ruling to this contract.
224	    /// Only the arbitrator must be allowed to call this function.
225	    /// Ruling 0 is reserved for "Not able/wanting to make a decision".
226	    ///
227	    /// @param _disputeID The identifier of the dispute in the Arbitrator contract.
228	    /// @param _ruling Ruling given by the arbitrator.
229	    function rule(uint256 _disputeID, uint256 _ruling) external override {
230	        require(msg.sender == address(arbitrator), ArbitratorOnly());
231	
232	        bytes32 disputeHash = disputeIDtoHash[_disputeID];
233	        RelayedData memory relayedData = disputeHashtoRelayedData[disputeHash];
234	
235	        // The first parameter of relayRule() `_messageSender` is missing from the encoding below
236	        // because Vea takes care of inserting it for security reasons.
237	        bytes4 methodSelector = IForeignGateway.relayRule.selector;
238	        bytes memory data = abi.encode(disputeHash, _ruling, relayedData.relayer);
239	        veaInbox.sendMessage(foreignGateway, methodSelector, data);
240	    }
241	
242	    // ************************************* //
243	    // *           Public Views            * //
244	    // ************************************* //
245	
246	    /// @notice Looks up the local home disputeID for a disputeHash
247	    /// @param _disputeHash dispute hash
248	    /// @return disputeID dispute identifier on the home chain
249	    function disputeHashToHomeID(bytes32 _disputeHash) external view override returns (uint256) {
250	        return disputeHashtoID[_disputeHash];
251	    }
252	
253	    function receiverGateway() external view override returns (address) {
254	        return foreignGateway;
255	    }
256	
257	    // ************************************* //
258	    // *              Errors               * //
259	    // ************************************* //
260	
261	    error OwnerOnly();
262	    error ArbitratorOnly();
263	    error FeesPaidInERC20Only();
264	    error FeesPaidInNativeCurrencyOnly();
265	    error ForeignChainIDNotSupported();
266	    error DisputeAlreadyRelayed();
267	    error TransferFailed();
268	    error AllowanceIncreaseFailed();
269	}

