     8	const deployForeignGateway: DeployFunction = async (hre: HardhatRuntimeEnvironment) => {
     9	  const { ethers, deployments, getNamedAccounts, getChainId, config } = hre;
    10	  const { execute } = deployments;
    11	  const { zeroPadValue, toBeHex } = ethers;
    12	
    13	  // fallback to hardhat node signers on local network
    14	  const deployer = (await getNamedAccounts()).deployer ?? (await hre.ethers.getSigners())[0].address;
