    21	  const homeNetwork = config.networks[network.companionNetworks.home] as HttpNetworkConfig;
    22	  const homeChainProvider = new ethers.JsonRpcProvider(homeNetwork.url);
    23	  let nonce = await homeChainProvider.getTransactionCount(deployer);
    24	  // HomeGatewayToEthereum Proxy deploy tx will be the 2nd tx after this on its
    25	  // home network, so we add 1 to the current nonce.
    26	  nonce += 1;
    27	  const homeGatewayAddress = getContractAddress(deployer, nonce);
    28	  console.log("calculated future HomeGatewayToEthereum address for nonce %d: %s", nonce, homeGatewayAddress);
