    47	  // TODO: set up the correct fees for the FORKING_COURT
    48	  const fee = (await core.courts(Courts.GENERAL)).feeForJuror;
    49	  await execute("ForeignGatewayOnEthereum", { from: deployer, log: true }, "changeCourtJurorFee", Courts.GENERAL, fee);
